agentMessages.content:
RESOLVED USER REQUEST

{{$flow.state.resolved_request}}

PURCHASING POLICY CONTEXT

{{$flow.state.policy_context}}

Classify the resolved request using only the supplied policy context.

Return one flat object matching the configured structured-output schema.

agentStructuredOutput.jsonSchema:
{
  "request_intent": {
    "type": "string",
    "required": true,
    "description": "The user's primary procurement question or objective, derived from the request"
  },
  "purchase_category": {
    "type": "string",
    "required": true,
    "description": "The purchase or contract category using the terminology found in the supplied policy; use 'not determined' if unsupported"
  },
  "estimated_value": {
    "type": "string",
    "required": true,
    "description": "The total estimated purchase, project, or contract value stated by the user; use 'not provided' if absent"
  },
  "funding_source": {
    "type": "string",
    "required": true,
    "description": "The funding source stated by the user or identified from context; use 'not provided' if absent"
  },
  "applicable_procurement_path": {
    "type": "string",
    "required": true,
    "description": "The procurement path that applies, expressed using terminology from the supplied policy; use 'not determined' if there is insufficient evidence"
  },
  "applicable_threshold": {
    "type": "string",
    "required": true,
    "description": "The monetary threshold or boundary relevant to the classification, exactly as supported by the policy; use 'not applicable' or 'not found' when appropriate"
  },
  "required_authority": {
    "type": "string",
    "required": true,
    "description": "The person, role, or governing body identified by the policy as responsible for approval, authorization, signature, or determination; use 'not identified' if unsupported"
  },
  "policy_section": {
    "type": "string",
    "required": true,
    "description": "The section number and heading of the policy supporting the classification"
  },
  "evidence_summary": {
    "type": "string",
    "required": true,
    "description": "A concise paraphrase of the policy evidence supporting the classification without adding requirements not found in the document"
  },
  "classification_reason": {
    "type": "string",
    "required": true,
    "description": "A concise explanation connecting the known facts in the user's request to the relevant policy provision"
  },
  "confidence": {
    "type": "string",
    "required": true,
    "description": "Confidence in the classification based only on the supplied policy evidence. Return exactly one of: high, medium, or low"
  }
}

